 static boolean available(){return ServerMenuClient.supports("task-tools");}
 private boolean split(){return width-nav.left()>=420;}
 private int listWidth(){return split()?Math.min(230,Math.max(150,(width-nav.left()-32)/3)):width-nav.left()-20;}
 private int x(){return split()?nav.left()+listWidth()+12:nav.left();}
 private int w(){return width-x()-20;}
 private int top(){return 38;}
 private int panelEnd(){if(!data.has("task"))return Math.min(height-64,top()+72);return Math.min(height-64,top()+Math.max(166,Math.min(360,98+lines.size()*24)));}
