 private void list(){var j=new JsonObject();j.addProperty("group",group);j.addProperty("query",query);j.addProperty("status",statusFilter);if(!cursor.isEmpty())j.addProperty("cursor",cursor);send("workList",j);}
 private void select(JsonObject task){if(busy){if(!Set.of("workList","workGet").contains(operation))return;ServerMenuClient.cancelReads(this);session.cancel();busy=false;}String next=Json.str(task,"id");if(next.equals(id)&&data.has("task"))return;id=next;taskTab="Обзор";data.remove("task");resetScroll();load();}
 String subscription(){return group.isEmpty()?"home|":"groups|"+group;}
