 private JsonObject body(){var j=new JsonObject();if(id.isEmpty()&&!cursor.isEmpty())j.addProperty("cursor",cursor);j.addProperty("group",group);if(!id.isEmpty()){j.addProperty("task",id);if(data.has("task"))j.add("revision",data.getAsJsonObject("task").get("revision"));}return j;}
 private void send(String op,JsonObject j){if(busy)return;j.addProperty("action","community");j.addProperty("section","home");j.addProperty("op",op);busy=true;retry=false;notice=Set.of("workList","workGet").contains(op)?"Загрузка…":"Сохраняем изменения…";operation=op;var packet=session.begin(j,!Set.of("workList","workGet").contains(op),System.currentTimeMillis());requestId=Json.str(packet,"request");ServerMenuClient.request(packet);if(!Set.of("workList","workGet").contains(op)||!listLoaded||!id.isEmpty()&&!data.has("task"))rebuildWidgets();}
