 private void row(String label,Runnable action){lines.add(label);actions.add(action);}
 private void paragraph(String text){var wrapped=font.getSplitter().splitLines(text,w()-24,net.minecraft.network.chat.Style.EMPTY);for(int i=0;i<wrapped.size();i+=2){var pair=new ArrayList<String>();pair.add(wrapped.get(i).getString());if(i+1<wrapped.size())pair.add(wrapped.get(i+1).getString());paragraphs.put(lines.size(),pair);row("",null);}}
 private void stageMenu(JsonObject stage,int index){minecraft.setScreen(new ChoicePopup(this,"Этап",List.of("Переименовать…","Удалить этап…"),choice->{if(choice==0){var preset=new JsonObject();preset.add("title",stage.get("title"));editor("Название этапа",List.of(new CommunityScreen.Field("title","Название",100)),preset,v->{var b=body();b.addProperty("index",index);b.add("title",v.get("title"));send("workSubtask",b);});}else minecraft.setScreen(new net.minecraft.client.gui.screens.ConfirmScreen(yes->{minecraft.setScreen(this);if(yes){var b=body();b.addProperty("index",index);b.addProperty("remove",true);send("workSubtask",b);}},Component.literal("Удалить этап?"),Component.literal(Json.str(stage,"title"))));}));}
 private void editor(String title,List<CommunityScreen.Field> fields,JsonObject preset,java.util.function.Consumer<JsonObject> callback){minecraft.setScreen(new TaskEditScreen(this,title,fields,preset,callback));}
 private void edit(JsonObject t){if(busy){notice="Дождитесь завершения текущего запроса";return;}var preset=new JsonObject();if(t!=null)for(String k:List.of("title","description"))preset.add(k,t.has(k)?t.get(k):new JsonPrimitive(""));editor(t==null?"Новая задача":"Изменить задачу",List.of(new CommunityScreen.Field("title","Название",100),new CommunityScreen.Field("description","Описание",1000)),preset,v->{var b=body();if(t==null){b.remove("task");b.remove("revision");}b.add("title",v.get("title"));b.add("description",v.has("description")?v.get("description"):new JsonPrimitive(""));send("workSave",b);});}
 private void textAction(String title,String key,int limit,String op){editor(title,List.of(new CommunityScreen.Field(key,title,limit)),new JsonObject(),v->{var b=body();b.add(key,v.get(key));send(op,b);});}
 private boolean planning(){return ServerMenuClient.supports("community-extensions");}
