  var codes=new ArrayList<String>();for(var e:deps){var d=e.getAsJsonObject();String code=Json.opt(d,"code","");codes.add(code);paragraph((d.get("done").getAsBoolean()?"Готово: ":"Ожидается: ")+code+" · "+Json.str(d,"title"));}
  if(manage)row("Изменить зависимости…",()->{var preset=new JsonObject();preset.addProperty("codes",String.join(", ",codes));editor("Коды блокирующих задач",List.of(new CommunityScreen.Field("codes","Коды через запятую; пусто — убрать",200)),preset,v->{var b=body();b.add("codes",v.get("codes"));send("workDependencies",b);});});
  int days=t.has("repeatDays")?t.get("repeatDays").getAsInt():0;var intervals=List.of(0,1,7,30);var labels=List.of("Не повторять","Каждый день","Каждые 7 дней","Каждые 30 дней");
  row("Повтор: "+labels.get(Math.max(0,intervals.indexOf(days)))+(manage?" ▾":""),manage?()->minecraft.setScreen(new ChoicePopup(this,"Повтор задачи",labels,n->{var b=body();b.addProperty("days",intervals.get(n));send("workRepeat",b);}).current(intervals.indexOf(days))):null);
  if(days>0)paragraph("Следующая отдельная задача: "+CommunityScreen.local(t.get("nextRepeatAt").getAsLong()));
