 private static String historyLabel(String op){return switch(op){case "workSave"->"Изменены название и описание";case "workStatus"->"Изменён статус";case "workAssign"->"Изменён ответственный";case "workDue"->"Изменён срок";case "workSubtask"->"Изменён этап";case "workResources"->"Изменены ресурсы";case "workDependencies"->"Изменены зависимости";case "workReserve"->"Изменён резерв";case "workRepeat"->"Изменён повтор";case "workComment"->"Добавлен комментарий";default->"Изменена задача";};}
