 private String nextCursor="";private String cursorNext(){return nextCursor;}
 
 private static String status(JsonObject t){return switch(Json.opt(t,"status","open")){case "working"->"В работе";case "done"->"Готово";default->"Открыта";};}
 public void receiveCommunity(JsonObject j){if(!session.receive(j))return;boolean wasBusy=busy;busy=false;boolean changed=false;
  if(j.has("error")){notice=Json.opt(j,"text","Не удалось выполнить действие");retry=!Set.of("INVALID","FORBIDDEN","NOT_FOUND","CONFLICT","EXPIRED").contains(Json.opt(j,"code",""));if(Json.opt(j,"code","").equals("CONFLICT")&&!(minecraft.screen instanceof TaskEditScreen)&&!(minecraft.screen instanceof TaskResourcesScreen)){load();return;}changed=true;}
  else{notice="";if(j.has("deleted")){for(int n=tasks.size()-1;n>=0;n--)if(Json.str(tasks.get(n).getAsJsonObject(),"id").equals(id))tasks.remove(n);id="";data.remove("task");rebuildWidgets();return;}
   if(j.has("tasks")){changed=!listLoaded||!tasks.equals(j.get("tasks"))||!nextCursor.equals(Json.opt(j,"nextCursor",""))||canCreate!=(j.has("canCreate")&&j.get("canCreate").getAsBoolean());tasks=j.getAsJsonArray("tasks").deepCopy();if(id.isEmpty()&&split()&&!tasks.isEmpty()){id=Json.str(tasks.get(0).getAsJsonObject(),"id");changed=true;}nextCursor=Json.opt(j,"nextCursor","");listLoaded=true;canCreate=j.has("canCreate")&&j.get("canCreate").getAsBoolean();if(!id.isEmpty()){if(changed)rebuildWidgets();load();return;}}
   if(j.has("task")){var task=j.getAsJsonObject("task");id=Json.str(task,"id");changed=!data.has("task")||!UiPayload.same(data.getAsJsonObject("task"),task);data.add("task",task.deepCopy());boolean found=false;for(int n=0;n<tasks.size();n++)if(Json.str(tasks.get(n).getAsJsonObject(),"id").equals(id)){tasks.set(n,task.deepCopy());found=true;break;}if(!found)tasks.add(task.deepCopy());}
  }if(changed||retry||wasBusy&&!Set.of("workList","workGet").contains(operation))rebuildWidgets();
 }
 private void resetList(){if(busy)return;if(!query.equals(listedQuery)||!statusFilter.equals(listedStatus)){id="";data.remove("task");taskTab="Обзор";resetScroll();}listedQuery=query;listedStatus=statusFilter;cursor="";searchAt=0;taskList.reset();list();}
 @Override public boolean keyPressed(int key,int scan,int modifiers){if((key==264||key==265)&&getFocused() instanceof CommunityCard focused){int at=-1;for(int n=0;n<tasks.size();n++)if(Json.str(tasks.get(n).getAsJsonObject(),"id").equals(focused.targetId())){at=n;break;}if(at>=0){int next=Math.max(0,Math.min(tasks.size()-1,at+(key==264?1:-1)));taskList.reveal(next);String target=Json.str(tasks.get(next).getAsJsonObject(),"id");rebuildWidgets();for(var c:children())if(c instanceof CommunityCard card&&card.targetId().equals(target)){setFocused(card);break;}return true;}}if((key==257||key==335)&&getFocused() instanceof EditBox){resetList();return true;}if(key==256&&!id.isEmpty()){id="";data.remove("task");rebuildWidgets();return true;}return super.keyPressed(key,scan,modifiers);}
 @Override public void tick(){if(searchAt>0&&!busy&&!retry&&System.currentTimeMillis()>=searchAt)resetList();if(dirty&&!busy&&!retry){dirty=false;list();}if(session.timeout(System.currentTimeMillis())){busy=false;retry=true;notice="Нет ответа. Повтор безопасен.";rebuildWidgets();}}
 @Override public boolean mouseScrolled(double mx,double my,double dx,double dy){if(nav.scroll(mx,dy)){rebuildWidgets();return true;}if((split()?mx<x():my<listBottom())&&taskList.scroll(my,dy)){rebuildWidgets();return true;}return super.mouseScrolled(mx,my,dx,dy);}
 @Override public boolean mouseClicked(double mx,double my,int button){if(taskList.click(mx,my,button)){rebuildWidgets();return true;}return super.mouseClicked(mx,my,button);}
 @Override public boolean mouseDragged(double mx,double my,int button,double dx,double dy){if(taskList.drag(my,button)){rebuildWidgets();return true;}return super.mouseDragged(mx,my,button,dx,dy);}
 @Override public boolean mouseReleased(double mx,double my,int button){taskList.release();return super.mouseReleased(mx,my,button);}
 @Override public void renderBackground(GuiGraphics g,int mx,int my,float d){super.renderBackground(g,mx,my,d);if(!id.isEmpty()){UiTheme.panel(g,x(),top(),w(),panelEnd()-top(),UiPalette.color(0xE81B252E));}}
 @Override public void render(GuiGraphics g,int mx,int my,float d){super.render(g,mx,my,d);UiHeading.page(g,font,title,width);taskList.draw(g);if((split()||id.isEmpty())&&tasks.isEmpty()&&!busy)UiEmptyState.draw(g,font,listLoaded?query.isBlank()&&statusFilter.isEmpty()?"Начните с первой задачи":"Задачи не найдены":"Загрузка…",query.isBlank()&&statusFilter.isEmpty()?"Нажмите «Новая задача» и добавьте первый шаг.":"Измените запрос или сбросьте фильтр кнопкой ×.",nav.left()+8,122,listWidth()-16,listBottom());if(data.has("task")){var task=data.getAsJsonObject("task");Ui.text(g,font,font.plainSubstrByWidth(Json.str(task,"title"),w()-108),x()+12,top()+14,UiKit.text(),false);UiBadge.draw(g,font,Json.opt(task,"code","")+" · "+status(task),x()+12,top()+29,w()-24,Json.opt(task,"status","open").equals("done")?UiPalette.color(0xFF79CBA6):UiPalette.color(0xFFF0A77C));}if(!data.has("task")&&split())UiEmptyState.draw(g,font,id.isEmpty()?"Ваш следующий шаг":"Открываем задачу…",id.isEmpty()?"Выберите карточку слева или создайте новую задачу.":"Получаем актуальные данные с сервера.",x()+12,top()+16,w()-24,top()+70);
  for(int n=firstRow;n<Math.min(lines.size(),firstRow+visibleRows);n++)if(actions.get(n)==null&&!stageChecks.containsKey(n)){int y=top()+82+(n-firstRow)*24;if(paragraphs.containsKey(n)){int line=0;for(String text:paragraphs.get(n))Ui.text(g,font,text,x()+12,y+2+12*line++,UiKit.text(),false);continue;}String item=resourceIcons.get(n);if(item!=null)TaskResourcesScreen.icon(g,item,x()+8,y+2);Ui.text(g,font,font.plainSubstrByWidth(lines.get(n),w()-(item==null?24:44)),x()+(item==null?12:30),y+5,UiPalette.color(0xD7E2EC));if(resourceProgress.containsKey(n)){g.fill(x()+30,y+19,x()+w()-24,y+21,UiPalette.color(0xFF394651));g.fill(x()+30,y+19,x()+30+(int)((w()-54)*resourceProgress.get(n)),y+21,UiPalette.color(0xFF79CBA6));}}Ui.status(g,font,notice,x(),height-56,w(),height-34);}
